<?php
require __DIR__.'/includes/bootstrap.php';
$pdo=database();$_SESSION['basket_csrf']??=bin2hex(random_bytes(32));$notice=$_SESSION['flash']??'';unset($_SESSION['flash']);
$catalog=portal_items();$items=[];$total=0;foreach($catalog as $item)if($item['pillar']==='Agri-Fishery'&&isset($_SESSION['basket'][$item['id']])){$qty=max(1,(int)$_SESSION['basket'][$item['id']]);$item['quantity']=$qty;$item['line_total']=(float)$item['price']*$qty;$total+=$item['line_total'];$items[]=$item;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{if(!hash_equals($_SESSION['basket_csrf'],(string)($_POST['_token']??'')))throw new RuntimeException('Your session expired. Please try again.');$action=(string)($_POST['action']??'');
  if($action==='update_basket'){$quantities=(array)($_POST['quantity']??[]);foreach($quantities as $id=>$qty){$id=(string)$id;$qty=(int)$qty;if($qty<=0){unset($_SESSION['basket'][$id]);}elseif(isset($_SESSION['basket'][$id]))$_SESSION['basket'][$id]=min(99,$qty);}$_SESSION['flash']='Basket updated.';header('Location: /basket.php');exit;}
  if($action==='place_order'){
   if(empty($_SESSION['account']['id']))throw new RuntimeException('Sign in before placing an order.');$q=$pdo->prepare("SELECT 1 FROM user_pillar_roles upr JOIN roles r ON r.id=upr.role_id WHERE upr.user_id=:uid AND upr.status='active' AND r.code='consumer_buyer'");$q->execute(['uid'=>(int)$_SESSION['account']['id']]);if(!$q->fetchColumn())throw new RuntimeException('Activate the Consumer / Buyer role before checkout.');
   $name=trim((string)($_POST['recipient_name']??''));$phone=trim((string)($_POST['phone']??''));$address=trim((string)($_POST['delivery_address']??''));$payment=(string)($_POST['payment_method']??'');if($name===''||$phone===''||$address===''||!in_array($payment,['Cash on delivery','Farm pickup'],true))throw new RuntimeException('Complete delivery contact details and choose a payment option.');
   $pdo->beginTransaction();$subtotal=0;$orderRows=[];$lookup=$pdo->prepare("SELECT id,title,price_minor FROM listings WHERE id=:id AND pillar='Agri-Fishery' AND item_type='Product' AND status='published'");foreach($_SESSION['basket']??[] as $id=>$qty){$lookup->execute(['id'=>(string)$id]);$listing=$lookup->fetch();if(!$listing)continue;$qty=max(1,min(99,(int)$qty));$subtotal+=(int)$listing['price_minor']*$qty;$orderRows[]=['listing'=>$listing,'qty'=>$qty];}if(!$orderRows)throw new RuntimeException('Your basket has no available products.');
   $q=$pdo->prepare("INSERT INTO orders(customer_user_id,status,currency,subtotal_minor,fulfillment_details) VALUES(:uid,'pending','PHP',:total,CAST(:details AS JSONB)) RETURNING id");$q->execute(['uid'=>(int)$_SESSION['account']['id'],'total'=>$subtotal,'details'=>json_encode(['recipient_name'=>$name,'phone'=>$phone,'delivery_address'=>$address,'payment_method'=>$payment],JSON_THROW_ON_ERROR)]);$orderId=(int)$q->fetchColumn();$line=$pdo->prepare('INSERT INTO order_items(order_id,listing_id,title_snapshot,quantity,unit_price_minor) VALUES(:oid,:listing,:title,:qty,:price)');foreach($orderRows as $entry)$line->execute(['oid'=>$orderId,'listing'=>$entry['listing']['id'],'title'=>$entry['listing']['title'],'qty'=>$entry['qty'],'price'=>$entry['listing']['price_minor']]);$pdo->commit();$_SESSION['basket']=[];$_SESSION['flash']='Order #'.$orderId.' placed. The seller will confirm fulfillment.';header('Location: /account.php?role=consumer_buyer&view=orders');exit;
  }
  throw new RuntimeException('Unknown basket action.');
 }catch(Throwable $e){if($pdo&&$pdo->inTransaction())$pdo->rollBack();$notice=$e instanceof PDOException?'Order could not be saved. Please check your database setup.':$e->getMessage();}
}
$pageTitle='Basket — Kabulig Market';require __DIR__.'/includes/header.php';
?>
<main class="site-page"><section class="site-page-hero account-compact-hero"><div class="container"><div class="eyebrow">KABULIG MARKET / SHOP</div><h1>Your <em>basket.</em></h1><p>Review your local products and place your order.</p></div></section><section class="section-pad"><div class="container basket-layout"><?php if($notice!==''): ?><div class="admin-notice"><?= h($notice) ?></div><?php endif; ?><?php if(!$items): ?><section class="account-content-panel basket-empty"><i class="fa-solid fa-basket-shopping"></i><h2>Your basket is empty</h2><p>Find fresh products from local farm and fishery sellers.</p><a class="btn btn-darkgreen" href="/agri-fishery/market.php">Browse Market / Shop</a></section><?php else: ?><div class="basket-list"><form method="post"><input type="hidden" name="_token" value="<?= h($_SESSION['basket_csrf']) ?>"><input type="hidden" name="action" value="update_basket"><?php foreach($items as $item): ?><article class="basket-item"><?php if(!empty($item['image_url'])): ?><img src="<?= h($item['image_url']) ?>" alt="<?= h($item['title']) ?>"><?php endif; ?><div><strong><?= h($item['title']) ?></strong><small><?= h($item['provider']) ?> · <?= h($item['location']) ?></small><span><?= money((float)$item['price']) ?> <?= h($item['unit']) ?></span></div><label>Qty<input type="number" name="quantity[<?= h($item['id']) ?>]" value="<?= (int)$item['quantity'] ?>" min="0" max="99"></label><b><?= money((float)$item['line_total']) ?></b></article><?php endforeach; ?><button class="btn btn-outline-green" type="submit">Update basket</button></form></div><aside class="basket-checkout-card"><div class="eyebrow">CHECKOUT</div><h2>Delivery details</h2><p>Choose pickup or cash on delivery. Payment details are not stored by the portal.</p><div class="basket-total"><span>Order total</span><strong><?= money($total) ?></strong></div><?php if(empty($_SESSION['account']['id'])): ?><div class="admin-notice">Sign in and enable Consumer / Buyer to place your order.</div><a class="btn btn-darkgreen w-100" href="/account.php#login">Sign in to checkout</a><?php else: ?><form method="post"><input type="hidden" name="_token" value="<?= h($_SESSION['basket_csrf']) ?>"><input type="hidden" name="action" value="place_order"><label>Recipient name<input name="recipient_name" value="<?= h($_SESSION['account']['name']) ?>" required></label><label>Phone number<input name="phone" type="tel" required></label><label>Delivery address<input name="delivery_address" required></label><label>Payment / fulfillment<select name="payment_method"><option>Cash on delivery</option><option>Farm pickup</option></select></label><button class="btn btn-darkgreen w-100" type="submit">Place order</button></form><?php endif; ?></aside><?php endif; ?></div></section></main><?php require __DIR__.'/includes/footer.php'; ?>
